      RECORD_STATUS_VALID
      | RECORD_STATUS_ROOT
      | RECORD_STATUS_TOPOLOGY_AUTHENTICATED
      | RECORD_STATUS_HOMOGENEOUS_DOMAIN_SUMMARY_EXACT
