  var ledger_gas_product_mass = 0.0;
  var ledger_visible_gas_product_mass = 0.0;
  var ledger_unplaced_gas_product_mass = 0.0;
  var sealed_box_gas_product_moles = 0.0;
  var reaction_heat = 0.0;
