    let vs = sv_corner_density(field_offset, source, x, y, z, resolution);
    let p0 = sv_interpolate(ps, sv_corner_position(target0, x, y, z, resolution), vs, sv_corner_density(field_offset, target0, x, y, z, resolution), isolation);
